import{_ as o,o as t,c as r,a4 as a}from"./chunks/framework.DA9C4Pbl.js";const g=JSON.parse('{"title":"Services","description":"","frontmatter":{"title":"Services","visibility":"public","audience":"operator","tier":"reference","source":"generated","cli":"4.3.3","template":"7.4"},"headers":[],"relativePath":"reference/compose/services.md","filePath":"reference/compose/services.md"}'),d={name:"reference/compose/services.md"};function s(n,e,c,i,l,h){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to “Services”">​</a></h1><p>What <code>docker-compose.yml</code> version 7.4 starts, generated from the file itself — the comments below are the file&#39;s own. <code>arcsecond status</code> lists the same services with their state; <code>arcsecond logs &lt;service&gt;</code> shows one&#39;s log.</p><table tabindex="0"><thead><tr><th>Service</th><th>Container</th><th>Image</th><th>Ports on the machine</th><th>Depends on</th><th>Optional</th></tr></thead><tbody><tr><td><code>db</code></td><td><code>arcsecond-db</code></td><td><code>postgres:16</code></td><td>none</td><td>—</td><td>no</td></tr><tr><td><code>broker</code></td><td><code>arcsecond-broker</code></td><td><code>redis:7.4</code></td><td>none</td><td>—</td><td>no</td></tr><tr><td><code>backend</code></td><td><code>arcsecond-api</code></td><td><code>ghcr.io/arcsecond-io/arcsecond-api:latest</code></td><td><code>127.0.0.1:8800:8800</code></td><td><code>db</code>, <code>broker</code></td><td>no</td></tr><tr><td><code>worker</code></td><td><code>arcsecond-worker</code></td><td><code>ghcr.io/arcsecond-io/arcsecond-api:latest</code></td><td>none</td><td><code>backend</code></td><td>no</td></tr><tr><td><code>dataworker</code></td><td><code>arcsecond-dataworker</code></td><td><code>ghcr.io/arcsecond-io/arcsecond-api:latest</code></td><td>none</td><td><code>backend</code></td><td>no</td></tr><tr><td><code>beat</code></td><td><code>arcsecond-beat</code></td><td><code>ghcr.io/arcsecond-io/arcsecond-api:latest</code></td><td>none</td><td><code>backend</code></td><td>no</td></tr><tr><td><code>platesolver</code></td><td><code>arcsecond-platesolver</code></td><td><code>ghcr.io/arcsecond-io/arcsecond-service-platesolver-astrometry:latest</code></td><td>none</td><td>—</td><td>no</td></tr><tr><td><code>web</code></td><td><code>arcsecond-web</code></td><td><code>ghcr.io/arcsecond-io/arcsecond-web:latest</code></td><td><code>5555:5555</code></td><td><code>backend</code></td><td>no</td></tr><tr><td><code>alerts</code></td><td><code>arcsecond-alerts</code></td><td><code>ghcr.io/arcsecond-io/arcsecond-api:latest</code></td><td>none</td><td><code>backend</code></td><td>yes (<code>alerts</code>)</td></tr></tbody></table><h2 id="db" tabindex="-1"><code>db</code> <a class="header-anchor" href="#db" aria-label="Permalink to “db”">​</a></h2><p>Database (PostgresQL)</p><ul><li><strong>Container</strong>: <code>arcsecond-db</code></li><li><strong>Image</strong>: <code>postgres:16</code></li><li><strong>Ports published on the machine</strong>: none — reachable from the other containers only</li><li><strong>Restart policy</strong>: <code>unless-stopped</code> — comes back with Docker after a reboot unless stopped on purpose</li><li><strong>Storage</strong>: <code>arcsecond_postgres_data:/var/lib/postgresql/data</code></li></ul><p>From the file:</p><blockquote><p>No host port. The backend reaches the DB over the internal Docker network (hostname <code>arcsecond-db</code>), and every CLI command that needs the DB (backups, restore, password rotation) goes through <code>docker exec</code> into this container. Publishing 5432 on the host bought nothing and failed the whole stack whenever another Postgres already held it. You must have a .env file with database credentials beside this yml file.</p></blockquote><h2 id="broker" tabindex="-1"><code>broker</code> <a class="header-anchor" href="#broker" aria-label="Permalink to “broker”">​</a></h2><p>Broker (Redis) - Shared messaging service between different services.</p><ul><li><strong>Container</strong>: <code>arcsecond-broker</code></li><li><strong>Image</strong>: <code>redis:7.4</code></li><li><strong>Ports published on the machine</strong>: none — reachable from the other containers only</li><li><strong>Restart policy</strong>: <code>unless-stopped</code> — comes back with Docker after a reboot unless stopped on purpose</li></ul><p>From the file:</p><blockquote><p>No host port either: Redis with no auth must never be reachable from outside the stack, and the backend reaches it over the Docker network.</p></blockquote><h2 id="backend" tabindex="-1"><code>backend</code> <a class="header-anchor" href="#backend" aria-label="Permalink to “backend”">​</a></h2><p>Arcsecond backend (REST APIs). Can be used for API calls and external pipelines, scripts etc.</p><ul><li><strong>Container</strong>: <code>arcsecond-api</code></li><li><strong>Image</strong>: <code>ghcr.io/arcsecond-io/arcsecond-api:latest</code></li><li><strong>Ports published on the machine</strong>: <code>127.0.0.1:8800:8800</code></li><li><strong>Starts after</strong>: <code>db</code>, <code>broker</code></li><li><strong>Restart policy</strong>: <code>unless-stopped</code> — comes back with Docker after a reboot unless stopped on purpose</li><li><strong>Healthcheck</strong>: yes — <code>arcsecond start</code> waits for it</li><li><strong>Time allowed to stop cleanly</strong>: <code>60s</code></li><li><strong>Storage</strong>: <code>${SHARED_DATA_PATH} → /data</code></li><li><strong>Reads from .env</strong>: <a href="./environment#shared-data-path"><code>SHARED_DATA_PATH</code></a>, <a href="./environment#arcsecond-backend-memory"><code>ARCSECOND_BACKEND_MEMORY</code></a></li></ul><p>From the file:</p><blockquote><p>This machine only. Browsers and other computers go through the webapp&#39;s port, which serves the very same API under /api/; 8800 is for the <code>arcsecond</code> command and scripts run on this computer. Published on every interface, it was a second, unneeded door onto the network. Allows the backend to reach the host machine via host.docker.internal. Required on Linux; Docker Desktop on Windows/macOS adds this automatically. You must have a .env file with secret keys beside this yml file. Leave /data as is, it&#39;s a path inside the container, not in the host machine. SHARED_DATA_PATH must be a path of your host machine, specified in the .env file. A ceiling, so no burst of work here can take the memory Postgres needs. Downloads no longer pass through these processes (the web container sends them), but rendering a large frame for review still does.</p></blockquote><h2 id="worker" tabindex="-1"><code>worker</code> <a class="header-anchor" href="#worker" aria-label="Permalink to “worker”">​</a></h2><p>Arcsecond worker, for offloading background work: the Control Room&#39;s exposures and procedures, and everything else someone is waiting on.</p><ul><li><strong>Container</strong>: <code>arcsecond-worker</code></li><li><strong>Image</strong>: <code>ghcr.io/arcsecond-io/arcsecond-api:latest</code></li><li><strong>Ports published on the machine</strong>: none — reachable from the other containers only</li><li><strong>Starts after</strong>: <code>backend</code></li><li><strong>Restart policy</strong>: <code>unless-stopped</code> — comes back with Docker after a reboot unless stopped on purpose</li><li><strong>Time allowed to stop cleanly</strong>: <code>120s</code></li><li><strong>Storage</strong>: <code>${SHARED_DATA_PATH} → /data</code></li><li><strong>Reads from .env</strong>: <a href="./environment#shared-data-path"><code>SHARED_DATA_PATH</code></a>, <a href="./environment#arcsecond-worker-memory"><code>ARCSECOND_WORKER_MEMORY</code></a></li></ul><p>From the file:</p><blockquote><p>The default queue only: the data worker below takes the rest. Leave /data as is, it&#39;s a path inside the container, not in the host machine. SHARED_DATA_PATH must be a path of your host machine, specified in the .env file.</p></blockquote><h2 id="dataworker" tabindex="-1"><code>dataworker</code> <a class="header-anchor" href="#dataworker" aria-label="Permalink to “dataworker”">​</a></h2><p>Arcsecond data worker, for the background work nobody at the telescope is waiting on: zip archives, previews of uploaded files, pushes to your storages, database backups, keograms, catalogue refreshes. On its own queue, so a long zip can never hold up a frame the observer is waiting for.</p><ul><li><strong>Container</strong>: <code>arcsecond-dataworker</code></li><li><strong>Image</strong>: <code>ghcr.io/arcsecond-io/arcsecond-api:latest</code></li><li><strong>Ports published on the machine</strong>: none — reachable from the other containers only</li><li><strong>Starts after</strong>: <code>backend</code></li><li><strong>Restart policy</strong>: <code>unless-stopped</code> — comes back with Docker after a reboot unless stopped on purpose</li><li><strong>Time allowed to stop cleanly</strong>: <code>120s</code></li><li><strong>Storage</strong>: <code>${SHARED_DATA_PATH} → /data</code></li><li><strong>Reads from .env</strong>: <a href="./environment#arcsecond-data-worker-concurrency"><code>ARCSECOND_DATA_WORKER_CONCURRENCY</code></a>, <a href="./environment#shared-data-path"><code>SHARED_DATA_PATH</code></a>, <a href="./environment#arcsecond-data-worker-memory"><code>ARCSECOND_DATA_WORKER_MEMORY</code></a></li></ul><p>From the file:</p><blockquote><p>Few at a time: this work is heavy and none of it is urgent. Leave /data as is, it&#39;s a path inside the container, not in the host machine. SHARED_DATA_PATH must be a path of your host machine, specified in the .env file.</p></blockquote><h2 id="beat" tabindex="-1"><code>beat</code> <a class="header-anchor" href="#beat" aria-label="Permalink to “beat”">​</a></h2><p>Arcsecond beat, to launch specific background tasks at specific times.</p><ul><li><strong>Container</strong>: <code>arcsecond-beat</code></li><li><strong>Image</strong>: <code>ghcr.io/arcsecond-io/arcsecond-api:latest</code></li><li><strong>Ports published on the machine</strong>: none — reachable from the other containers only</li><li><strong>Starts after</strong>: <code>backend</code></li><li><strong>Restart policy</strong>: <code>unless-stopped</code> — comes back with Docker after a reboot unless stopped on purpose</li><li><strong>Time allowed to stop cleanly</strong>: <code>30s</code></li></ul><h2 id="platesolver" tabindex="-1"><code>platesolver</code> <a class="header-anchor" href="#platesolver" aria-label="Permalink to “platesolver”">​</a></h2><p>Arcsecond plate solver service, for solving coordinates from raw images.</p><ul><li><strong>Container</strong>: <code>arcsecond-platesolver</code></li><li><strong>Image</strong>: <code>ghcr.io/arcsecond-io/arcsecond-service-platesolver-astrometry:latest</code></li><li><strong>Ports published on the machine</strong>: none — reachable from the other containers only</li><li><strong>Restart policy</strong>: <code>unless-stopped</code> — comes back with Docker after a reboot unless stopped on purpose</li></ul><p>From the file:</p><blockquote><p>No host port. Only the backend calls the solver, over the internal Docker network; it has no authentication and nothing outside the stack needs it.</p></blockquote><h2 id="web" tabindex="-1"><code>web</code> <a class="header-anchor" href="#web" aria-label="Permalink to “web”">​</a></h2><p>Arcsecond webapp. Served on 5555 only: a self-hosted install is organisation-based and therefore always a portal, so the second port that used to be here (5577) served the very same app.</p><ul><li><strong>Container</strong>: <code>arcsecond-web</code></li><li><strong>Image</strong>: <code>ghcr.io/arcsecond-io/arcsecond-web:latest</code></li><li><strong>Ports published on the machine</strong>: <code>5555:5555</code></li><li><strong>Starts after</strong>: <code>backend</code></li><li><strong>Restart policy</strong>: <code>unless-stopped</code> — comes back with Docker after a reboot unless stopped on purpose</li><li><strong>Storage</strong>: <code>${SHARED_DATA_PATH} → /data</code></li><li><strong>Reads from .env</strong>: <a href="./environment#arcsecond-downloads-per-client"><code>ARCSECOND_DOWNLOADS_PER_CLIENT</code></a>, <a href="./environment#arcsecond-downloads-total"><code>ARCSECOND_DOWNLOADS_TOTAL</code></a>, <a href="./environment#arcsecond-download-rate"><code>ARCSECOND_DOWNLOAD_RATE</code></a>, <a href="./environment#shared-data-path"><code>SHARED_DATA_PATH</code></a></li></ul><p>From the file:</p><blockquote><p>Download limits: how many downloads one computer may have open at once, how many in total, and the speed of each (bytes per second, k and m allowed, 0 for none). They keep downloads from filling the link a remote observer drives the telescope through. The same folder, read-only: this container sends the stored files itself, once the backend has said who may read them.</p></blockquote><h2 id="alerts" tabindex="-1"><code>alerts</code> <a class="header-anchor" href="#alerts" aria-label="Permalink to “alerts”">​</a></h2><p>Arcsecond transient-alerts consumer (optional). Long-lived Kafka client for NASA GCN. Outbound TLS only — nothing listens: auth.gcn.nasa.gov on 443, then kafka, kafka1, kafka2 and kafka3.gcn.nasa.gov on 9092. Requires GCN_CONSUMER_CLIENT_ID / GCN_CONSUMER_CLIENT_SECRET in .env; idles harmlessly when they are absent. Single instance only — do not scale it.</p><ul><li><strong>Container</strong>: <code>arcsecond-alerts</code></li><li><strong>Image</strong>: <code>ghcr.io/arcsecond-io/arcsecond-api:latest</code></li><li><strong>Ports published on the machine</strong>: none — reachable from the other containers only</li><li><strong>Starts after</strong>: <code>backend</code></li><li><strong>Restart policy</strong>: <code>unless-stopped</code> — comes back with Docker after a reboot unless stopped on purpose</li><li><strong>Time allowed to stop cleanly</strong>: <code>30s</code></li><li><strong>Optional</strong>: added with <code>arcsecond setup --with-alerts</code>, removed with <code>--without-alerts</code></li></ul>',44)])])}const b=o(d,[["render",s]]);export{g as __pageData,b as default};
